import{_ as a,o as i,c as t,a2 as e}from"./chunks/framework.BFIoSwgX.js";const k=JSON.parse('{"title":"Быстрый старт","description":"Установите зависимости SymbolTrail, постройте индекс проекта и выполните первый запрос через CLI.","frontmatter":{"title":"Быстрый старт","description":"Установите зависимости SymbolTrail, постройте индекс проекта и выполните первый запрос через CLI.","section":"Начало работы"},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),l={name:"getting-started.md"};function n(p,s,h,d,o,r){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="быстрыи-старт" tabindex="-1">Быстрый старт <a class="header-anchor" href="#быстрыи-старт" aria-label="Permalink to &quot;Быстрый старт&quot;">​</a></h1><p class="st-lead">От исходников проекта до первого запроса к графу.</p><h2 id="подготовка" tabindex="-1">Подготовка <a class="header-anchor" href="#подготовка" aria-label="Permalink to &quot;Подготовка&quot;">​</a></h2><p>Чтобы запустить SymbolTrail из исходников, нужны Node.js 20.19+ и npm. Git нужен для истории изменений и анализа диффа. Для установки нативных зависимостей могут понадобиться системные инструменты сборки.</p><p>В командах ниже <code>/path/to/symboltrail-source</code> обозначает каталог исходников самого инструмента. Вместо <code>/path/to/project</code> подставьте проект, который хотите исследовать. Сайт документации запускается из отдельного репозитория.</p><h2 id="_1-установите-зависимости" tabindex="-1">1. Установите зависимости <a class="header-anchor" href="#_1-установите-зависимости" aria-label="Permalink to &quot;1. Установите зависимости&quot;">​</a></h2><p>Откройте исходный репозиторий SymbolTrail:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/symboltrail-source</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /web/ui</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>Все следующие команды выполняются из этого каталога.</p><h2 id="_2-построите-индекс" tabindex="-1">2. Постройте индекс <a class="header-anchor" href="#_2-построите-индекс" aria-label="Permalink to &quot;2. Постройте индекс&quot;">​</a></h2><p>Передайте путь к исследуемому проекту:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> filegraph</span></span></code></pre></div><p>Индекс появится в <code>.SymbolTrail/db/&lt;имя-индекса&gt;/index.sqlite</code> внутри исходного репозитория инструмента. Каталог <code>.SymbolTrail/index-roots.json</code> хранит состав индексов и выбранный <code>active</code>.</p><div class="tip custom-block"><p class="custom-block-title">Уже есть другие индексы?</p><p>Новая сборка не обязательно меняет <code>active</code>. Проверьте его в каталоге индексов или задайте <code>FILEGRAPH_SET=&lt;имя-индекса&gt;</code> при запросе. Подробнее об этом в разделе <a href="/symbolTrail/indexing.html#выбор-индекса">«Индексация»</a>.</p></div><h2 id="_3-выполните-первыи-запрос" tabindex="-1">3. Выполните первый запрос <a class="header-anchor" href="#_3-выполните-первыи-запрос" aria-label="Permalink to &quot;3. Выполните первый запрос&quot;">​</a></h2><p>Проверьте подключение запросом циклов импортов. Для него не нужно заранее знать имена функций:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp:cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;cycles({ queries: [{}] })&#39;</span></span></code></pre></div><p>CLI вернёт текстовую карточку. Если выборка пуста, в выбранном индексе циклы не найдены. Это допустимый результат.</p><p>Чтобы найти конкретное объявление, подставьте его имя вместо <code>foo</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp:cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;find({ queries: [{ name: &quot;foo&quot; }] })&#39;</span></span></code></pre></div><p>Доступные запросы и их ограничения описаны на странице <a href="/symbolTrail/tools.html">«Инструменты»</a>.</p><h2 id="_4-включите-обновление" tabindex="-1">4. Включите обновление <a class="header-anchor" href="#_4-включите-обновление" aria-label="Permalink to &quot;4. Включите обновление&quot;">​</a></h2><p>Если будете менять исходники, запустите наблюдение в отдельном терминале:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> filegraph:watch</span></span></code></pre></div><p>Watch сначала строит индекс, затем обновляет его после сохранения файлов. Чтобы остановить watch, нажмите <code>Ctrl+C</code>.</p><h2 id="открыть-веб-интерфеис" tabindex="-1">Открыть веб-интерфейс <a class="header-anchor" href="#открыть-веб-интерфеис" aria-label="Permalink to &quot;Открыть веб-интерфейс&quot;">​</a></h2><p>Установите его зависимости и запустите локальный сервер:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web/ui</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ui</span></span></code></pre></div><p>Откройте адрес, который напечатает Vite. В интерфейсе можно выбрать индекс и репозиторий, найти код и открыть страницы файлов и символов. Интерфейс читает подготовленный индекс. Чтобы обновить связи, запустите watch или соберите индекс заново.</p><p>Обзор возможностей и пример размещения скриншота есть в разделе <a href="/symbolTrail/local-ui.html">«Локальный интерфейс»</a>.</p><h2 id="подключить-агента" tabindex="-1">Подключить агента <a class="header-anchor" href="#подключить-агента" aria-label="Permalink to &quot;Подключить агента&quot;">​</a></h2><p>Чтобы работать из редактора, настройте <a href="/symbolTrail/mcp.html">подключение MCP</a>. Запуск CLI не добавляет инструменты в агентский клиент.</p>`,32)])])}const g=a(l,[["render",n]]);export{k as __pageData,g as default};
